  'user.login.infos': 'NEXTPlutus เป็นเครื่องมือเสริมการวิเคราะห์หุ้นแบบหลายตัวแทนด้วย AI และไม่มีคุณสมบัติในการให้คำปรึกษาด้านการลงทุนในหลักทรัพย์ผลการวิเคราะห์ คะแนน และความคิดเห็นอ้างอิงทั้งหมดในแพลตฟอร์มถูกสร้างขึ้นโดยอัตโนมัติโดย AI ตามข้อมูลในอดีต และใช้เพื่อการเรียนรู้ การวิจัย และการแลกเปลี่ยนทางเทคนิคเท่านั้น และไม่ถือเป็นคำแนะนำในการลงทุนหรือพื้นฐานการตัดสินใจใดๆการลงทุนในหุ้นเกี่ยวข้องกับความเสี่ยงต่างๆ เช่น ความเสี่ยงด้านตลาด ความเสี่ยงด้านสภาพคล่อง ความเสี่ยงด้านนโยบาย ฯลฯ ซึ่งอาจนำไปสู่การสูญเสียเงินต้นได้ผู้ใช้ควรตัดสินใจอย่างอิสระโดยพิจารณาจากการยอมรับความเสี่ยงของตนเอง และพฤติกรรมการลงทุนและผลที่ตามมาที่เกิดจากการใช้เครื่องมือนี้จะต้องตกเป็นภาระของผู้ใช้ตลาดมีความเสี่ยงและการลงทุนต้องระมัดระวัง',
