  'user.login.privacy.view': 'ดูนโยบายความเป็นส่วนตัวของผู้ใช้',
  'user.login.privacy.collapse': 'ปิดข้อกำหนดความเป็นส่วนตัวของผู้ใช้',
  'user.login.privacy.content': 'เราให้ความสำคัญกับความเป็นส่วนตัวและการปกป้องข้อมูลของคุณ 1) ขอบเขตของการรวบรวม: เฉพาะข้อมูลที่จำเป็นในการใช้งานฟังก์ชัน (เช่น อีเมล หมายเลขโทรศัพท์มือถือ รหัสพื้นที่ ที่อยู่กระเป๋าสตางค์ของ Web3) และบันทึกและข้อมูลอุปกรณ์ที่จำเป็นเท่านั้นที่จะถูกรวบรวม 2) วัตถุประสงค์การใช้งาน: สำหรับการเข้าสู่ระบบบัญชีและการตรวจสอบความปลอดภัยการให้บริการฟังก์ชั่น การแก้ไขปัญหาและข้อกำหนดการปฏิบัติตาม 3) การจัดเก็บและความปลอดภัย: ข้อมูลได้รับการเข้ารหัสและจัดเก็บและมีการใช้สิทธิ์ที่จำเป็นและมาตรการควบคุมการเข้าถึงเพื่อป้องกันการเข้าถึง การเปิดเผย หรือการสูญหายโดยไม่ได้รับอนุญาต 4) การแบ่งปันกับบุคคลที่สาม: เว้นแต่กฎหมายและข้อบังคับกำหนดไว้หรือจำเป็นในการให้บริการ ข้อมูลส่วนบุคคลของคุณจะไม่ถูกแบ่งปันกับบุคคลที่สามหากเกี่ยวข้องกับบริการของบุคคลที่สาม (เช่น กระเป๋าเงิน ผู้ให้บริการ SMS) จะถูกประมวลผลในขอบเขตขั้นต่ำที่จำเป็นเพื่อใช้งานฟังก์ชันนี้เท่านั้น 5) คุกกี้/ที่เก็บข้อมูลในเครื่อง: ใช้สำหรับสถานะการเข้าสู่ระบบและการบำรุงรักษาเซสชันที่จำเป็น (เช่น โทเค็น PHPSESSID) คุณสามารถล้างหรือจำกัดได้ในเบราว์เซอร์ 6) สิทธิ์ส่วนบุคคล: คุณสามารถใช้สิทธิ์ของคุณในการสอบถาม แก้ไข ลบ เพิกถอนความยินยอม ฯลฯ ตามกฎหมายและข้อบังคับ 7) การเปลี่ยนแปลงและประกาศ: เมื่อมีการอัปเดตข้อกำหนดเหล่านี้จะแสดงอย่างเด่นชัดบนหน้าเว็บการใช้บริการนี้ต่อไปจะถือว่าคุณได้อ่านและยอมรับเนื้อหาที่อัปเดตแล้วหากคุณไม่ยอมรับข้อกำหนดเหล่านี้หรือการปรับปรุงใด ๆ โปรดหยุดใช้บริการและติดต่อเรา',
