  "dashboard.indicator.guide.section1.dataColumnsList": "<code>เวลา</code> (เวลา, วินาที), <code>เปิด</code>, <code>สูงสุด</code>, <code>ต่ำสุด</code>, <code>ปิด</code>, <code>ปริมาณ</code>",
  "dashboard.indicator.guide.section1.dataDesc": "ระบบจะแปลงข้อมูล K-line ปัจจุบันให้เป็นอ็อบเจ็กต์ Pandas DataFrame โดยอัตโนมัติ โดยชื่อตัวแปรคือ <code>df</code>",
  "dashboard.indicator.guide.section1.dataIndex": "สำคัญ: ดัชนี df เป็นการประทับเวลา (DatetimeIndex) โปรดรักษาดัชนีนี้ไว้ หลีกเลี่ยงการใช้ <code>.values</code> ซึ่งจะทำให้สูญเสียดัชนีไป",
