  "dashboard.indicator.guide.section2.desc": "คุณสามารถกำหนดตัวแปรเป็นพารามิเตอร์ได้ที่ต้นโค้ด ระบบจะพยายามแยกวิเคราะห์คำสั่งเช่น <code>variable = value</code> เป็นพารามิเตอร์ที่ปรับเปลี่ยนได้",
