  "dashboard.indicator.guide.section3.desc": "หากคุณต้องการให้ตัวชี้วัดของคุณรองรับการทดสอบย้อนหลัง คุณต้องตั้งค่าคอลัมน์สองคอลัมน์ต่อไปนี้ในโค้ดของคุณ: <strong>must__QD_TOKEN_1:",
  "dashboard.indicator.guide.section3.title": "3. การตั้งค่าสัญญาณทดสอบย้อนหลัง (สำคัญ!)",
