  "dashboard.indicator.guide.section5.table.color": "สีเส้น (รูปแบบเลขฐานสิบหก เช่น '#ff0000') หากไม่ได้กรอก ระบบจะกำหนดให้โดยอัตโนมัติ",
  "dashboard.indicator.guide.section5.table.data": "รายการข้อมูล ความยาวต้องตรงกับจำนวนแถวใน df แนะนำให้ใช้ <code>series.tolist()</code>",
  "dashboard.indicator.guide.section5.table.desc": "คำอธิบาย",
