  "user.login.infos": "QuantDinger เป็นเครื่องมือวิเคราะห์หุ้นแบบ AI หลายเอเจนต์ ซึ่งไม่มีคุณสมบัติในการให้คำปรึกษาด้านการลงทุนในหลักทรัพย์ ผลการวิเคราะห์ คะแนน และความคิดเห็นอ้างอิงทั้งหมดบนแพลตฟอร์มนั้นสร้างขึ้นโดยอัตโนมัติโดย AI จากข้อมูลในอดีต และมีไว้สำหรับการเรียนรู้ การวิจัย และการแลกเปลี่ยนทางเทคนิคเท่านั้น ไม่ถือเป็นคำแนะนำในการลงทุนหรือเป็นพื้นฐานในการตัดสินใจ การลงทุนในหุ้นมีความเสี่ยงด้านตลาด ความเสี่ยงด้านสภาพคล่อง ความเสี่ยงด้านนโยบาย และความเสี่ยงอื่นๆ ซึ่งอาจนำไปสู่การสูญเสียเงินต้น ผู้ใช้ควรตัดสินใจอย่างอิสระตามความสามารถในการรับความเสี่ยงของตนเอง และรับผิดชอบต่อผลที่ตามมาจากการลงทุนใดๆ ที่ใช้เครื่องมือนี้ ความเสี่ยงด้านตลาด การลงทุนจึงต้องระมัดระวัง",
  "user.login.legal.agree": "ฉันได้อ่านและยอมรับข้อจำกัดความรับผิดทางกฎหมายแล้ว",
  "user.login.legal.collapse": "ซ่อนข้อจำกัดความรับผิดทางกฎหมาย",
  "user.login.legal.content": "QuantDinger เป็นเครื่องมือวิเคราะห์หุ้นแบบ AI หลายเอเจนต์ และไม่ได้ให้คำแนะนำด้านการลงทุน ผลการวิเคราะห์ คะแนน และข้อมูลอ้างอิงทั้งหมดสร้างขึ้นโดย AI โดยอิงจากข้อมูลในอดีต และมีไว้เพื่อการเรียนรู้ การวิจัย และการแลกเปลี่ยนทางเทคนิคเท่านั้น ไม่ถือเป็นคำแนะนำด้านการลงทุนหรือเป็นพื้นฐานในการตัดสินใจ การลงทุนในหุ้นมีความเสี่ยงด้านตลาด สภาพคล่อง และนโยบาย ซึ่งอาจนำไปสู่การสูญเสียเงินต้น ผู้ใช้ควรตัดสินใจอย่างอิสระตามระดับความเสี่ยงที่ยอมรับได้ และรับผิดชอบต่อผลที่เกิดขึ้นจากการลงทุนและผลลัพธ์ที่ได้จากการใช้เครื่องมือนี้",
  "user.login.legal.required": "โปรดอ่านและตรวจสอบข้อจำกัดความรับผิดชอบทางกฎหมายก่อน",
