  "user.login.privacy.collapse": "ซ่อนนโยบายความเป็นส่วนตัว",
  "user.login.privacy.content": "เราให้ความสำคัญกับความเป็นส่วนตัวและการคุ้มครองข้อมูลของคุณ (1) ขอบเขตการเก็บรวบรวม: เราเก็บรวบรวมเฉพาะข้อมูลที่จำเป็นสำหรับการให้บริการ (เช่น อีเมล หมายเลขโทรศัพท์มือถือ รหัสประเทศ ที่อยู่กระเป๋าเงิน Web3) และข้อมูลบันทึก/ข้อมูลอุปกรณ์ในจำนวนจำกัด (2) วัตถุประสงค์ในการใช้งาน: การเข้าสู่ระบบบัญชีและการตรวจสอบความปลอดภัย การจัดเตรียมคุณสมบัติ การแก้ไขปัญหา และข้อกำหนดด้านการปฏิบัติตามกฎระเบียบ (3) การจัดเก็บและความปลอดภัย: ข้อมูลจะถูกเข้ารหัสและควบคุมการเข้าถึงเพื่อป้องกันการเข้าถึง การเปิดเผย หรือการสูญหายโดยไม่ได้รับอนุญาต (4) การแบ่งปันและบุคคลที่สาม: เราจะไม่แบ่งปันข้อมูลส่วนบุคคลกับบุคคลที่สาม ยกเว้นในกรณีที่กฎหมายกำหนดหรือเพื่อการให้บริการ ในกรณีที่เกี่ยวข้องกับบริการของบุคคลที่สาม (เช่น กระเป๋าเงิน ผู้ให้บริการ SMS) การประมวลผลจะจำกัดอยู่เพียงขอบเขตขั้นต่ำที่จำเป็น (5) คุกกี้/พื้นที่จัดเก็บข้อมูลในเครื่อง: ใช้สำหรับเซสชันและสถานะการเข้าสู่ระบบ (เช่น โทเค็น PHPSESSID) คุณสามารถล้างหรือจำกัดได้ในเบราว์เซอร์ของคุณ (6) สิทธิ์ของคุณ: คุณสามารถใช้สิทธิ์ในการเข้าถึง การแก้ไข การลบ และการถอนความยินยอมได้ตามที่กฎหมายอนุญาต (7) การเปลี่ยนแปลงและประกาศ: เราจะแจ้งให้ทราบอย่างชัดเจนเกี่ยวกับการอัปเดต การใช้งานอย่างต่อเนื่องแสดงว่าคุณได้อ่านและยอมรับข้อกำหนดที่ได้รับการปรับปรุงแล้ว หากคุณไม่เห็นด้วย โปรดหยุดใช้บริการและติดต่อเรา",
